import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { t, text, label, locale } from '../util';
import { fieldValue, linkTo, reviewField, safeUrl } from '../../common/labels';
import { typeBadge, statusPill, progressPill, gradedBadge, conditionPill, owner, backdrop } from './bits';
import ItemEditModal from './ItemEditModal';
import Link from 'flarum/common/components/Link';
import Tooltip from 'flarum/common/components/Tooltip';
import { startShowOff } from '../showOff';
import addToMyCollection from '../copyItem';
import useStyles from '../styles';
import Stars from './Stars';
const LONG = 600;

/** IGDB's genre names in the reader's language, when Curio has a word for them. */
const genre = name => {
  const key = 'ernestdefoe-curio.forum.genre.' + name.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
  return app.translator.translations[key] ? app.translator.trans(key) : name;
};

/** One item: its photos, details, the owner's notes and what the forum knows about it, in the reader's language. */
export default class ItemModal extends Modal {
  oninit(vnode) {
    super.oninit(vnode);
    useStyles();
    this.item = null;
    this.photo = 0;
    this.expanded = false;
    app.store.find('curio-items', this.attrs.itemId).then(item => this.item = item).catch(() => this.missing = true).finally(() => m.redraw());
  }
  className() {
    return 'CurioItemModal Modal--large';
  }
  title() {
    return this.item ? this.item.displayTitle() : '';
  }
  content() {
    if (this.missing) return m("div", {
      className: "Modal-body"
    }, t('item.missing'));
    if (!this.item) return m("div", {
      className: "Modal-body"
    }, m(LoadingIndicator, {
      display: "block"
    }));
    const item = this.item;
    const collection = item.collection();
    const type = collection?.type();
    const work = item.work();
    const photos = item.photos() || [];
    const pictures = photos.length ? photos.map(p => p.url) : work && work.coverUrl() ? [work.coverUrl()] : [];
    const mine = app.session.user && collection && collection.user() === app.session.user;
    return m("div", {
      className: "Modal-body CurioItem"
    }, m("div", {
      className: 'CurioItem-gallery CurioItem-gallery--' + (type ? type.shape() : 'portrait')
    }, m("div", {
      className: "CurioItem-photo",
      style: backdrop(pictures[this.photo] || pictures[0])
    }, pictures.length ? m("img", {
      src: pictures[this.photo] || pictures[0],
      alt: item.displayTitle()
    }) : m(Icon, {
      name: type ? type.icon() : 'fas fa-box-open'
    }), pictures.length > 1 ? m("span", {
      className: "CurioItem-photoCount"
    }, m(Icon, {
      name: "fas fa-camera"
    }), " ", this.photo + 1, " / ", pictures.length) : null), pictures.length > 1 ? m("div", {
      className: "CurioItem-thumbs"
    }, photos.map((p, i) => m("button", {
      type: "button",
      className: 'CurioItem-thumb' + (i === this.photo ? ' active' : ''),
      onclick: () => this.photo = i,
      "aria-label": text('item.photo_n', {
        n: i + 1
      })
    }, m("img", {
      src: p.small,
      alt: ""
    })))) : null, !mine && item.canEdit() ?
    // A moderator's Edit on someone else's item, kept apart from what members do with it.
    m("div", {
      className: "CurioItem-moderate"
    }, m(Tooltip, {
      text: text('item.edit_this')
    }, m(Button, {
      className: "Button Button--icon Button--rounded",
      icon: "fas fa-pen",
      "aria-label": text('item.edit_this'),
      onclick: () => this.edit(item, collection)
    }))) : null), m("div", {
      className: "CurioItem-info"
    }, m("div", {
      className: "CurioItem-badges"
    }, typeBadge(type), statusPill(item.status()), progressPill(item, type), gradedBadge(item, type), item.favourite() ? m("span", {
      className: "CurioFav"
    }, m(Icon, {
      name: "fas fa-star"
    }), " ", t('item.favourite')) : null), m("h2", {
      className: "CurioItem-title"
    }, item.displayTitle(), " ", item.year() ? m("span", {
      className: "CurioMuted"
    }, "(", item.year(), ")") : null), item.subtitle() ? m("div", {
      className: "CurioItem-sub"
    }, item.subtitle()) : null, this.ratingLine(item, type), this.facts(item, type, work), item.notes() ? m("blockquote", {
      className: "CurioItem-notes"
    }, owner(collection?.user(), true), m("p", null, item.notes())) : null, work ? this.about(work) : null, this.offers(item), this.actions(item, collection, mine)));
  }

  /** The stars, and "Read my review" when the type has a review link and it is filled. */
  ratingLine(item, type) {
    const review = reviewField(type ? type.fields() : []);
    const url = review && safeUrl((item.fields() || {})[review.key]);
    if (!item.rating() && !url) return null;
    return m("div", {
      className: "CurioItem-rating"
    }, item.rating() ? m(Stars, {
      value: item.rating()
    }) : null, url ? m("span", {
      className: "CurioItem-review"
    }, linkTo(url.href, [m(Icon, {
      name: "fas fa-arrow-up-right-from-square"
    }), ' ', t('item.read_review')])) : null);
  }
  facts(item, type, work) {
    const fields = type ? type.fields() || [] : [];
    const values = item.fields() || {};
    const rows = [];
    const known = work && work.facts() || {};
    const list = names => (names || []).join(', ');

    // What the look-up knows about the title (IGDB for games).
    if (known.developer) rows.push([t('item.developer'), list(known.developer)]);
    if (known.publisher) rows.push([t('item.publisher'), list(known.publisher)]);
    if (known.released) rows.push([t('item.released'), dayjs(known.released).format('LL')]);
    if (known.genres) rows.push([t('item.genres'), list(known.genres.map(genre))]);
    if (known.platforms) rows.push([t('item.platforms'), list(known.platforms)]);
    const review = reviewField(fields);
    fields.forEach(f => {
      const v = values[f.key];
      if (v === undefined || v === null || v === '') return;
      // Shown beside the rating instead.
      if (f === review && safeUrl(v)) return;
      rows.push([label(f.labels), f.kind === 'bool' ? t(v ? 'item.yes' : 'item.no') : fieldValue(f, v, locale())]);
    });
    if (item.condition()) rows.push([t('item.condition'), conditionPill(type, item.condition())]);
    if (item.acquiredOn()) rows.push([t('item.acquired'), dayjs(item.acquiredOn()).format('LL')]);
    if (item.pricePaid() !== null && item.pricePaid() !== undefined) {
      rows.push([m("span", null, t('item.price'), " ", m(Icon, {
        name: "fas fa-lock",
        className: "CurioLock"
      })), new Intl.NumberFormat(locale(), {
        style: 'currency',
        currency: item.priceCurrency() || 'USD'
      }).format(item.pricePaid())]);
    }
    if (!rows.length) return null;
    return m("dl", {
      className: "CurioItem-facts"
    }, rows.map(([k, v]) => m("div", null, m("dt", null, k), m("dd", null, v))));
  }

  /**
   * What the forum knows about the title, in the reader's language only. When
   * that is missing (or just Wikidata's one-liner), the English text waits
   * behind a toggle.
   */
  about(work) {
    const own = work.description();
    const other = work.fallback();
    const language = other && new Intl.DisplayNames([locale()], {
      type: 'language'
    }).of(other.locale);
    return m("section", {
      className: "CurioItem-about"
    }, m("h4", null, t('item.about')), own ? this.paragraph(own) : m("p", {
      className: "CurioMuted"
    }, t('item.no_description')), own ? m("div", {
      className: "CurioItem-source"
    }, this.credit(work.descriptionSource(), work.sourceUrl()), work.languages() > 1 ? m("span", {
      className: "CurioItem-langs"
    }, m(Icon, {
      name: "fas fa-language"
    }), " ", t('item.languages', {
      count: work.languages()
    })) : null) : null, other ? m(Button, {
      className: "Button Button--link CurioToggle",
      "aria-expanded": this.showOther ? 'true' : 'false',
      onclick: () => this.showOther = !this.showOther
    }, t(this.showOther ? 'item.hide_other' : 'item.show_other', {
      language
    })) : null, other && this.showOther ? m("div", {
      className: "CurioItem-other",
      lang: other.locale
    }, this.paragraph(other.description), m("div", {
      className: "CurioItem-source"
    }, this.credit(other.source, other.url))) : null);
  }
  paragraph(text) {
    const long = text.length > LONG;
    return [m("p", null, long && !this.expanded ? text.slice(0, text.lastIndexOf(' ', LONG)) + ' …' : text), long ? m(Button, {
      className: "Button Button--link CurioToggle",
      onclick: () => this.expanded = !this.expanded
    }, this.expanded ? t('item.less') : t('item.more')) : null];
  }
  credit(source, url) {
    if (source === 'wikipedia') return m("a", {
      href: url,
      target: "_blank",
      rel: "noopener noreferrer"
    }, m(Icon, {
      name: "fab fa-wikipedia-w"
    }), " ", t('item.from_wikipedia'));
    if (source === 'deepl') return m("span", null, t('item.translated_deepl'));
    if (source === 'wikidata') return m("span", null, t('item.from_wikidata'));
    return null;
  }

  /** On a wanted item: who has it open to trade. */
  offers(item) {
    const offers = item.tradeOffers && item.tradeOffers();
    if (!offers || !offers.count) return null;
    return m(Link, {
      className: "CurioOffers",
      href: app.route('curio.collection', {
        id: offers.collectionId
      }) + `?item=${offers.itemId}`,
      onclick: () => app.modal.close()
    }, m(Icon, {
      name: "fas fa-right-left"
    }), " ", t('item.offers', {
      count: offers.count
    }));
  }
  actions(item, collection, mine) {
    const discussed = item.discussionId() ? m(Link, {
      className: "Button CurioItem-discussed",
      href: app.route('discussion', {
        id: item.discussionId()
      }),
      onclick: () => app.modal.close()
    }, m(Icon, {
      name: "far fa-comments",
      className: "Button-icon"
    }), m("span", {
      className: "Button-label"
    }, t('item.discussed'))) : null;
    if (mine) {
      return m("div", {
        className: "CurioItem-actions"
      }, m(Button, {
        className: "Button Button--primary",
        icon: "fas fa-pen",
        onclick: () => this.edit(item, collection)
      }, t('item.edit')), discussed || (item.status() !== 'wishlist' ? m(Button, {
        className: "Button",
        icon: "fas fa-bullhorn",
        onclick: () => startShowOff(item)
      }, t('item.show_off')) : null));
    }
    const canAdd = app.forum.attribute('canCreateCurio') && app.session.user;

    // Someone else's item: "I have this too" and "Add to my wishlist" stay for
    // everyone; a moderator's Edit sits under the cover.
    return m("div", {
      className: "CurioItem-actions"
    }, canAdd ? m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => this.copy(item, 'owned')
    }, t('item.have_too')) : null, canAdd ? m(Button, {
      className: "Button",
      icon: "far fa-heart",
      onclick: () => this.copy(item, 'wishlist')
    }, t('item.want_it')) : null, discussed);
  }
  edit(item, collection) {
    app.modal.show(ItemEditModal, {
      item,
      collection,
      onsave: () => this.attrs.onchange && this.attrs.onchange(),
      ondelete: () => this.attrs.onchange && this.attrs.onchange()
    });
  }

  /** "I have this too" / "Add to my wishlist": into any of my collections, those of the same type first. */
  copy(item, status) {
    addToMyCollection({
      prefill: item,
      status,
      typeIds: [item.collection().type().id()]
    });
  }
}
flarum.reg.add('ernestdefoe-curio', 'forum/components/ItemModal', ItemModal);